const LEGACY_QUESTIONS = [
 {id:'g01',domain:'general',difficulty:'debutant',q:'Quel processus transforme un sédiment meuble en roche sédimentaire ?',context:'On considère un dépôt qui s’enfouit progressivement dans un bassin.',a:['La diagenèse','La fusion partielle','La sublimation','La différenciation magmatique'],correct:0,explain:'La diagenèse regroupe notamment la compaction et la cimentation qui transforment les sédiments en roche.'},
 {id:'g02',domain:'general',difficulty:'debutant',q:'Quelle roche est typiquement issue du refroidissement lent d’un magma en profondeur ?',context:'La vitesse de refroidissement influence la taille des cristaux.',a:['Basalte','Granite','Obsidienne','Tuf'],correct:1,explain:'Le granite est une roche magmatique plutonique dont le refroidissement lent permet la croissance de cristaux visibles.'},
 {id:'g03',domain:'general',difficulty:'intermediaire',q:'Quel principe permet d’affirmer que, dans une série sédimentaire non renversée, une couche est plus ancienne que celle qui la recouvre ?',context:'On suppose que la série n’a pas été bouleversée par une tectonique postérieure.',a:['Principe d’inclusion','Principe de recoupement','Principe de superposition','Principe d’actualisme'],correct:2,explain:'Dans une série non renversée, les couches inférieures se sont déposées avant celles qui les recouvrent.'},
 {id:'g04',domain:'general',difficulty:'avance',q:'Une faille recoupe une unité sédimentaire mais est elle-même scellée par une couche non déformée. Que peut-on conclure ?',context:'Aucun indice ne suggère une réactivation ultérieure.',a:['La faille est plus récente que la couche scellante','La faille est antérieure au dépôt de la couche scellante','La faille et la couche ont nécessairement le même âge','L’âge relatif ne peut jamais être établi'],correct:1,explain:'Le principe de recoupement indique que la faille est postérieure à l’unité recoupée. Le scellement montre qu’elle est antérieure au dépôt de la couche qui la recouvre.'},
 {id:'g05',domain:'general',difficulty:'intermediaire',q:'Quelle limite sépare la croûte terrestre du manteau supérieur ?',context:'Cette discontinuité est reconnue grâce aux changements de vitesse des ondes sismiques.',a:['Gutenberg','Lehmann','Mohorovičić (Moho)','Conrad uniquement'],correct:2,explain:'Le Moho est la discontinuité sismique séparant la croûte du manteau.'},
 {id:'g06',domain:'general',difficulty:'avance',q:'Pourquoi les zircons sont-ils souvent utilisés en géochronologie U-Pb ?',context:'On recherche un minéral capable de conserver une information isotopique ancienne.',a:['Ils incorporent facilement beaucoup de plomb initial','Ils excluent souvent le plomb lors de leur cristallisation et résistent à l’altération','Ils se forment uniquement dans les sédiments récents','Leur âge dépend directement de leur couleur'],correct:1,explain:'Le zircon incorpore l’uranium dans son réseau cristallin, généralement peu de plomb initial, et peut préserver le système isotopique.'},
 {id:'p01',domain:'petroleum',difficulty:'debutant',q:'Quels éléments sont indispensables à un système pétrolier conventionnel fonctionnel ?',context:'On veut expliquer la génération, l’accumulation et la conservation des hydrocarbures.',a:['Roche mère, migration, réservoir, piège et couverture','Uniquement une roche poreuse','Uniquement une faille ouverte','Un volcan actif et une nappe phréatique'],correct:0,explain:'Un système pétrolier comprend une roche mère mature, une voie de migration, un réservoir, un piège et une couverture efficace, avec une chronologie favorable.'},
 {id:'p02',domain:'petroleum',difficulty:'debutant',q:'Quel est le rôle principal d’une roche couverture efficace ?',context:'Un réservoir poreux contient des hydrocarbures sous pression.',a:['Augmenter systématiquement la porosité du réservoir','Empêcher ou limiter la fuite des hydrocarbures','Générer obligatoirement les hydrocarbures','Remplacer le piège structural'],correct:1,explain:'Une couverture peu perméable limite la migration verticale ou latérale des hydrocarbures hors du piège.'},
 {id:'p03',domain:'petroleum',difficulty:'intermediaire',q:'Pourquoi la synchronisation est-elle essentielle dans un système pétrolier ?',context:'Un piège peut être géométriquement favorable mais se former tardivement.',a:['Le piège doit exister au moment de la charge ou avant celle-ci','La roche mère doit toujours être plus jeune que le réservoir','La couverture doit se déposer après la fuite des hydrocarbures','La migration n’a aucun rapport avec la chronologie'],correct:0,explain:'La formation du piège, la maturation, la migration et la mise en place de la couverture doivent être compatibles dans le temps.'},
 {id:'p04',domain:'petroleum',difficulty:'intermediaire',q:'Une roche mère riche en matière organique n’est pas assez mature thermiquement. Quelle conséquence est la plus probable ?',context:'La richesse organique est favorable, mais la transformation thermique reste limitée.',a:['Production maximale garantie','Génération d’hydrocarbures potentiellement insuffisante','Porosité du réservoir forcément nulle','Formation automatique d’un piège'],correct:1,explain:'La richesse organique est un potentiel, mais la maturation thermique contrôle la transformation de la matière organique en hydrocarbures.'},
 {id:'p05',domain:'petroleum',difficulty:'avance',q:'Une fermeture structurale est cartographiée, mais les contacts fluides et les données de charge sont incertains. Quelle approche est la plus robuste ?',context:'La décision d’exploration doit expliciter les incertitudes.',a:['Déclarer la découverte certaine sur la seule fermeture','Évaluer séparément géométrie, charge, réservoir, couverture et risques, puis intégrer les probabilités','Ignorer les données de puits','Remplacer l’analyse par une valeur unique de porosité'],correct:1,explain:'Une évaluation de prospect sépare les éléments du système pétrolier et documente les incertitudes avant l’intégration du risque.'},
 {id:'p06',domain:'petroleum',difficulty:'avance',q:'Dans un piège mixte, quelle combinaison décrit le mieux sa géométrie ?',context:'Le piège peut associer une structure et un changement latéral de faciès.',a:['Seulement une fermeture anticlinale','Seulement une discordance régionale','Une composante structurale et une composante stratigraphique','Une roche mère sans réservoir'],correct:2,explain:'Un piège mixte associe des éléments structuraux et stratigraphiques, par exemple une faille et une variation latérale de faciès.'},
 {id:'pt01',domain:'petrophysics',difficulty:'debutant',q:'Que mesure principalement une diagraphie gamma ray (GR) ?',context:'Le GR est souvent utilisé pour distinguer des niveaux argileux de niveaux plus propres.',a:['La radioactivité naturelle de la formation','La pression de pore directement','La perméabilité absolue directement','La vitesse de forage uniquement'],correct:0,explain:'Le gamma ray mesure la radioactivité naturelle. Il aide à estimer l’argilosité, mais son interprétation dépend de la minéralogie et du contexte.'},
 {id:'pt02',domain:'petrophysics',difficulty:'debutant',q:'Une porosité de 20 % signifie que, dans un volume de roche donné…',context:'On distingue le volume des vides du volume total.',a:['20 % du volume total correspond aux pores','20 % de la roche est nécessairement du pétrole','La perméabilité vaut 20 mD','La saturation en eau vaut 20 %'],correct:0,explain:'La porosité est le rapport du volume des pores au volume total de la roche. Elle ne renseigne pas seule sur le fluide ni sur la connectivité des pores.'},
 {id:'pt03',domain:'petrophysics',difficulty:'intermediaire',q:'Selon la loi d’Archie dans une formation propre, quelle donnée contribue directement à estimer la saturation en eau ?',context:'On suppose que les hypothèses d’Archie sont adaptées et que les paramètres sont calibrés.',a:['La résistivité de formation et la résistivité de l’eau, avec porosité et exposants','Le gamma ray seul','La profondeur seule','Le diamètre du trépan seul'],correct:0,explain:'La relation d’Archie relie la résistivité de formation, la résistivité de l’eau, la porosité et la saturation. Elle est moins adaptée aux roches argileuses sans corrections.'},
 {id:'pt04',domain:'petrophysics',difficulty:'intermediaire',q:'Le neutron porosity et la densité donnent des porosités très différentes dans une zone gazifère. Quelle explication est plausible ?',context:'Les outils neutron et densité répondent différemment aux propriétés de la formation et des fluides.',a:['L’effet gaz peut créer un croisement neutron-densité','Le gaz rend toujours toutes les diagraphies identiques','La densité ne réagit jamais à la lithologie','Le croisement prouve à lui seul une accumulation commerciale'],correct:0,explain:'Le gaz peut réduire l’indice hydrogène vu par le neutron et affecter la densité apparente, produisant un croisement caractéristique qui doit être vérifié avec d’autres données.'},
 {id:'pt05',domain:'petrophysics',difficulty:'avance',q:'Pourquoi faut-il être prudent en appliquant Archie à un grès fortement argileux ?',context:'Les argiles peuvent conduire l’électricité en plus de l’eau interstitielle.',a:['Archie suppose une contribution conductrice dominée par l’eau dans une matrice propre','Archie ne peut jamais être utilisé en grès','L’argile augmente toujours la résistivité','La saturation en eau devient indépendante de la résistivité'],correct:0,explain:'La conduction de surface liée aux argiles peut conduire à surestimer la saturation en eau si le modèle n’est pas adapté. Des modèles shaly-sand peuvent être nécessaires.'},
 {id:'pt06',domain:'petrophysics',difficulty:'avance',q:'Un intervalle présente une porosité élevée, une saturation en eau élevée et une faible perméabilité estimée. Quelle conclusion est la plus défendable ?',context:'Il s’agit d’une interprétation intégrée, non d’une décision de production définitive.',a:['Réservoir commercial garanti','La porosité seule suffit à prouver un bon débit','Le potentiel productif reste incertain : fluides, connectivité et qualité réservoir doivent être évalués','La roche ne contient aucun pore'],correct:2,explain:'La porosité ne garantit ni la connectivité des pores ni une saturation en hydrocarbures favorable. La perméabilité et les données de pression/production sont importantes.'},
 {id:'s01',domain:'sedimentology',difficulty:'debutant',q:'Quel environnement est fréquemment associé à des rides de courant et à des stratifications obliques ?',context:'Ces structures résultent du déplacement de grains par un fluide.',a:['Un environnement sans mouvement de fluide','Un courant transportant des sédiments','Une cristallisation métamorphique','Une intrusion granitique profonde'],correct:1,explain:'Les rides de courant et les stratifications obliques sont des structures formées par la migration de formes de fond sous l’action d’un courant.'},
 {id:'s02',domain:'sedimentology',difficulty:'intermediaire',q:'Une séquence granodécroissante vers le haut est souvent compatible avec…',context:'La taille des grains diminue progressivement au sommet de la séquence.',a:['Une diminution de l’énergie du courant au cours du dépôt','Une augmentation continue de l’énergie uniquement','Une cristallisation de magma','Un métamorphisme régional obligatoire'],correct:0,explain:'Une séquence granodécroissante peut traduire la diminution de l’énergie ou de la compétence du courant, par exemple lors du remplissage d’un chenal ou d’un événement de dépôt.'},
 {id:'s03',domain:'sedimentology',difficulty:'avance',q:'Deux grès ont une granulométrie similaire, mais des géométries de corps très différentes. Quel facteur peut expliquer cette différence ?',context:'Les faciès se ressemblent à l’échelle de l’échantillon, mais leur architecture varie.',a:['Uniquement la couleur des grains','L’environnement de dépôt et l’architecture sédimentaire','Le nom de la formation seulement','La granulométrie interdit toute variation de géométrie'],correct:1,explain:'L’environnement de dépôt contrôle la géométrie, la continuité et l’empilement des corps sédimentaires, au-delà de la granulométrie ponctuelle.'},
 {id:'s04',domain:'sedimentology',difficulty:'debutant',q:'Quelle roche se forme principalement par accumulation et lithification de débris carbonatés ou de boues calcaires ?',context:'On cherche une roche sédimentaire carbonatée courante.',a:['Quartzite','Calcaire','Gneiss','Péridotite'],correct:1,explain:'Le calcaire est une roche sédimentaire composée majoritairement de minéraux carbonatés, souvent de calcite.'},
 {id:'st01',domain:'structural',difficulty:'debutant',q:'Dans une faille normale, quel compartiment s’abaisse par rapport à l’autre ?',context:'La géométrie est celle d’un régime extensif classique.',a:['Le toit par rapport au mur','Le mur par rapport au toit','Les deux compartiments restent toujours à la même altitude','Aucun déplacement n’est possible'],correct:0,explain:'Dans une faille normale, le compartiment situé au-dessus du plan de faille (toit) se déplace vers le bas relativement au mur.'},
 {id:'st02',domain:'structural',difficulty:'intermediaire',q:'Quel régime tectonique est généralement associé aux failles inverses et aux chevauchements ?',context:'Le raccourcissement horizontal est dominant.',a:['Extension','Compression','Absence de contrainte','Uniquement dissolution'],correct:1,explain:'Les failles inverses et chevauchements accommodent un raccourcissement et sont associés à un régime compressif.'},
 {id:'st03',domain:'structural',difficulty:'avance',q:'Une couche repère est décalée de part et d’autre d’une faille. Que faut-il pour estimer le rejet réel ?',context:'Une carte en surface peut ne montrer qu’une composante du déplacement.',a:['Mesurer uniquement la longueur de la faille','Connaître la géométrie du plan, l’orientation de la couche et le décalage observé','Utiliser seulement la couleur de la roche','Supposer systématiquement un rejet vertical'],correct:1,explain:'Le rejet réel dépend de la géométrie tridimensionnelle du déplacement. Le décalage apparent sur une coupe ou une carte peut n’en représenter qu’une composante.'},
 {id:'m01',domain:'mineralogy',difficulty:'debutant',q:'Quel minéral est le constituant principal de la plupart des grès quartzitiques ?',context:'On considère une roche détritique très riche en grains résistants.',a:['Quartz','Halite','Gypse','Graphite'],correct:0,explain:'Le quartz est très résistant à l’altération et fréquent dans les grès. Un quartz-arénite contient une forte proportion de grains de quartz.'},
 {id:'m02',domain:'mineralogy',difficulty:'debutant',q:'Quelle propriété est testée par le trait d’un minéral ?',context:'Le test se fait généralement sur une plaque de porcelaine non émaillée.',a:['La couleur de sa poudre','Sa densité exacte','Sa température de fusion','Sa radioactivité uniquement'],correct:0,explain:'Le trait est la couleur de la poudre du minéral et peut être plus diagnostique que sa couleur extérieure.'},
 {id:'m03',domain:'mineralogy',difficulty:'intermediaire',q:'Un minéral présente deux directions de clivage presque à 90°. Quel minéral courant peut montrer ce caractère ?',context:'On combine le clivage avec d’autres propriétés pour l’identification.',a:['Quartz','Feldspath','Grenat','Olivine uniquement'],correct:1,explain:'Les feldspaths présentent typiquement deux directions de clivage proches de 90°. L’identification complète demande d’autres critères.'},
 {id:'m04',domain:'mineralogy',difficulty:'avance',q:'Pourquoi une roche métamorphique peut-elle présenter une foliation ?',context:'La roche a été soumise à des conditions de pression et de température variables.',a:['L’alignement préférentiel de minéraux ou la ségrégation minéralogique sous déformation','L’absence totale de contraintes','La seule évaporation de l’eau de mer','Une cimentation détritique sans transformation'],correct:0,explain:'La foliation résulte notamment de l’orientation préférentielle de minéraux plats ou allongés et/ou de la ségrégation de minéraux lors du métamorphisme et de la déformation.'},
 {id:'h01',domain:'hydro',difficulty:'debutant',q:'Qu’est-ce qu’un aquifère ?',context:'On s’intéresse à une formation géologique capable de stocker et transmettre de l’eau.',a:['Une formation qui peut stocker et transmettre de l’eau en quantité exploitable','Toute roche imperméable','Une couche de magma','Une zone nécessairement salée'],correct:0,explain:'Un aquifère est une formation géologique suffisamment perméable pour stocker et transmettre de l’eau souterraine.'},
 {id:'h02',domain:'hydro',difficulty:'intermediaire',q:'Selon la loi de Darcy, à gradient hydraulique comparable, que provoque généralement une hausse de conductivité hydraulique ?',context:'On suppose un écoulement laminaire dans un milieu poreux saturé.',a:['Une baisse du débit spécifique','Une hausse du flux d’écoulement','L’annulation du gradient','Une inversion automatique du sens d’écoulement'],correct:1,explain:'La loi de Darcy relie le flux au produit de la conductivité hydraulique et du gradient hydraulique, dans les conditions où ses hypothèses s’appliquent.'},
 {id:'h03',domain:'hydro',difficulty:'avance',q:'Une baisse de niveau piézométrique apparaît dans plusieurs puits après une longue période de pompage. Quelle interprétation faut-il tester en priorité ?',context:'Les précipitations et les mesures doivent également être examinées.',a:['Une baisse du niveau est toujours une erreur instrumentale','L’effet du pompage sur la charge hydraulique, en le distinguant de la variabilité naturelle et de la recharge','Une augmentation certaine de la recharge','La disparition de toute porosité dans l’aquifère'],correct:1,explain:'Le pompage peut provoquer un rabattement. Il faut analyser les séries temporelles, les débits, la recharge, les puits voisins et les incertitudes de mesure.'},
 {id:'gf01',domain:'geophysics',difficulty:'debutant',q:'Quelle méthode géophysique image les contrastes d’impédance acoustique à partir des réflexions d’ondes ?',context:'La méthode est centrale en exploration du sous-sol profond.',a:['Sismique réflexion','Magnétométrie seule','Mesure du pH','Granulométrie laser'],correct:0,explain:'La sismique réflexion enregistre les ondes réfléchies aux interfaces où l’impédance acoustique varie.'},
 {id:'gf02',domain:'geophysics',difficulty:'intermediaire',q:'Une anomalie gravimétrique positive peut être compatible avec…',context:'L’interprétation dépend du contraste de densité et de la géométrie de la source.',a:['Un excès de masse relatif au modèle régional','Uniquement une cavité remplie d’air','La présence certaine de pétrole','Une roche ayant obligatoirement une faible densité'],correct:0,explain:'Une anomalie gravimétrique positive peut refléter un excès de masse par rapport au modèle de référence, mais plusieurs géométries et lithologies peuvent la produire.'},
 {id:'gf03',domain:'geophysics',difficulty:'avance',q:'Pourquoi une interprétation sismique doit-elle être calibrée par des données de puits ?',context:'Les vitesses, la lithologie et les marqueurs stratigraphiques peuvent être incertains.',a:['Pour convertir et relier les temps sismiques aux profondeurs et aux marqueurs géologiques','Parce que la sismique fournit toujours directement une lithologie unique','Pour supprimer toute incertitude','Parce que les données de puits sont inutiles sans sismique'],correct:0,explain:'Les données de puits, notamment les checkshots/VSP et les logs, aident à la calibration temps-profondeur et à l’identification des horizons.'},
 {id:'mp01',domain:'mapping',difficulty:'debutant',q:'À quoi sert principalement un système de coordonnées de référence (SCR/CRS) dans un SIG ?',context:'Des couches doivent être superposées correctement sur une carte.',a:['Définir comment les coordonnées représentent la position sur la Terre','Changer automatiquement la lithologie','Calculer la porosité','Remplacer les métadonnées'],correct:0,explain:'Le système de coordonnées de référence précise le datum et la projection éventuelle, ce qui permet de positionner et comparer correctement les données spatiales.'},
 {id:'mp02',domain:'mapping',difficulty:'intermediaire',q:'Pourquoi deux couches SIG peuvent-elles sembler décalées même si leurs coordonnées sont numériques ?',context:'Les couches ont été produites par des organismes différents.',a:['Elles peuvent utiliser des systèmes de coordonnées ou datums différents','Les fichiers vectoriels ne contiennent jamais de coordonnées','Les coordonnées n’ont pas d’unité possible','Une carte ne peut contenir qu’une seule couche'],correct:0,explain:'Un SCR absent, mal déclaré ou différent peut provoquer un décalage. Il faut vérifier le CRS source et effectuer une transformation correcte si nécessaire.'},
 {id:'mp03',domain:'mapping',difficulty:'avance',q:'Tu calcules une distance en degrés de longitude entre deux points près de l’équateur. Pourquoi cette distance n’est-elle pas directement une distance métrique fiable ?',context:'Les degrés sont des unités angulaires, et leur équivalent métrique varie avec la latitude.',a:['Parce que les coordonnées géographiques sont angulaires et que la longueur dépend de la latitude et de la géométrie terrestre','Parce que la longitude n’existe qu’en mer','Parce que tous les degrés valent exactement 1 km','Parce qu’une distance ne peut pas être calculée dans un SIG'],correct:0,explain:'Les degrés ne sont pas des unités métriques uniformes. Pour des mesures de distance/surface, on choisit une projection adaptée à la zone et à l’objectif.'},
 {id:'gc01',domain:'geochem',difficulty:'debutant',q:'Quel processus chimique contribue fortement à l’altération des feldspaths en milieu humide ?',context:'Les eaux légèrement acides interagissent avec les minéraux silicatés.',a:['Hydrolyse','Fusion nucléaire','Compaction mécanique seule','Magnétisation'],correct:0,explain:'L’hydrolyse transforme notamment les feldspaths en minéraux secondaires comme les argiles, selon les conditions du milieu.'},
 {id:'gc02',domain:'geochem',difficulty:'intermediaire',q:'Lors d’une étude de contamination, pourquoi comparer les concentrations mesurées à un fond géochimique local ?',context:'Certaines concentrations naturelles varient fortement selon la lithologie.',a:['Pour distinguer autant que possible les anomalies liées aux activités humaines des niveaux naturels','Pour prouver que toute valeur élevée est anthropique','Pour ignorer la géologie locale','Pour convertir les concentrations en coordonnées GPS'],correct:0,explain:'Le fond géochimique local tient compte des variations naturelles liées aux roches et aux sols. Il aide à interpréter les anomalies, sans suffire à lui seul à prouver leur origine.'},
 {id:'gc03',domain:'geochem',difficulty:'avance',q:'Deux échantillons ont des teneurs en métal similaires, mais des contextes lithologiques différents. Quelle pratique améliore l’interprétation ?',context:'Les teneurs naturelles et la mobilité des éléments peuvent dépendre de la matrice.',a:['Comparer sans tenir compte de la matrice','Stratifier les comparaisons par lithologie et contexte géochimique, avec contrôle qualité analytique','Éliminer systématiquement le résultat le plus élevé','Conclure immédiatement à une pollution'],correct:1,explain:'Le contexte lithologique, la granulométrie, la matière organique et la qualité analytique peuvent influencer les teneurs. Les comparaisons doivent contrôler ces facteurs.'},
 {id:'g07',domain:'general',difficulty:'intermediaire',q:'Quelle différence essentielle distingue une roche métamorphique d’une roche sédimentaire ?',context:'On compare les processus de formation dominants.',a:['Le métamorphisme transforme une roche à l’état solide sous l’effet de pression, température et fluides','Toute roche métamorphique est fondue','Toute roche sédimentaire est cristalline','Une roche sédimentaire ne peut jamais être déformée'],correct:0,explain:'Le métamorphisme modifie minéralogie et texture principalement à l’état solide, sans fusion complète obligatoire.'},
 {id:'p07',domain:'petroleum',difficulty:'intermediaire',q:'Pourquoi un grès peut-il présenter une bonne porosité mais une faible perméabilité ?',context:'Les pores peuvent être petits, mal connectés ou partiellement obstrués.',a:['Parce que la porosité décrit le volume des vides, tandis que la perméabilité dépend de leur connectivité et de la géométrie des passages','Parce que porosité et perméabilité sont toujours identiques','Parce que la perméabilité dépend uniquement de la couleur','Cela est physiquement impossible'],correct:0,explain:'La porosité mesure le volume des vides ; la perméabilité reflète la facilité de circulation du fluide à travers un réseau poreux connecté.'},
 {id:'pt07',domain:'petrophysics',difficulty:'intermediaire',q:'Pourquoi corriger les logs de densité et de neutron des effets de trou ?',context:'Le diamètre du puits et la boue peuvent perturber la réponse des outils.',a:['Les conditions de trou peuvent modifier la réponse mesurée et biaiser les estimations','Les corrections servent uniquement à colorer les courbes','Les outils sont insensibles au trou','La correction transforme toujours la porosité en perméabilité'],correct:0,explain:'Les effets de trou, la boue, le cake et les conditions d’acquisition peuvent affecter les mesures. Les corrections et contrôles de qualité doivent précéder l’interprétation.'},
 {id:'s05',domain:'sedimentology',difficulty:'intermediaire',q:'Des fentes de dessiccation conservées dans des sédiments indiquent généralement…',context:'Le sédiment fin a été exposé à l’air puis s’est contracté.',a:['Un épisode d’émersion et de dessiccation','Un dépôt uniquement en grande profondeur océanique','Une intrusion magmatique','Une augmentation de la pression lithostatique seule'],correct:0,explain:'Les mud cracks se forment souvent lorsque des sédiments fins humides se dessèchent à l’air libre, même si le contexte doit être vérifié.'},
 {id:'st04',domain:'structural',difficulty:'intermediaire',q:'Qu’est-ce qu’un pli anticlinal dans son interprétation géométrique classique ?',context:'On décrit une structure plissée, sans présumer de son âge relatif avant vérification.',a:['Un pli convexe vers le haut, dont les flancs s’éloignent de la charnière','Un pli concave vers le haut uniquement','Une faille sans déplacement','Une surface d’érosion horizontale'],correct:0,explain:'Un anticlinal est un pli convexe vers le haut. Pour établir l’âge des couches au cœur, il faut tenir compte d’éventuels renversements et du contexte structural.'},
 {id:'m05',domain:'mineralogy',difficulty:'intermediaire',q:'Quelle combinaison aide le plus à identifier un minéral sur le terrain ?',context:'Aucune propriété isolée n’est toujours suffisante.',a:['Dureté, clivage, trait, éclat et densité relative','Uniquement le nom donné par un autre observateur','Uniquement la taille de l’échantillon','La position GPS seule'],correct:0,explain:'L’identification fiable combine plusieurs propriétés physiques et le contexte géologique.'},
 {id:'h04',domain:'hydro',difficulty:'intermediaire',q:'Quelle est la différence entre porosité et perméabilité en hydrogéologie ?',context:'On veut caractériser à la fois le stockage et la circulation.',a:['La porosité concerne les vides ; la perméabilité décrit la facilité de circulation à travers le milieu','Ce sont deux mots pour la même propriété','La porosité mesure seulement la vitesse de l’eau','La perméabilité ne dépend jamais des fractures'],correct:0,explain:'La porosité décrit le volume de vides, tandis que la perméabilité est liée à la connectivité et à la géométrie des voies d’écoulement.'},
 {id:'gf04',domain:'geophysics',difficulty:'intermediaire',q:'Quelle méthode est particulièrement sensible aux contrastes de susceptibilité magnétique ?',context:'Elle est fréquemment utilisée pour cartographier certaines intrusions ou structures.',a:['Magnétométrie','Sismique réflexion uniquement','Essai de pompage','Diffraction des rayons X seulement'],correct:0,explain:'La magnétométrie mesure les variations du champ magnétique associées notamment aux contrastes de susceptibilité des roches.'},
 {id:'mp04',domain:'mapping',difficulty:'intermediaire',q:'Quel est l’intérêt d’associer un identifiant unique à chaque échantillon géologique dans une base de données SIG ?',context:'Les analyses de laboratoire doivent être reliées aux observations de terrain.',a:['Garantir la traçabilité entre prélèvement, localisation, analyses et rapports','Améliorer automatiquement la précision GPS','Éliminer la nécessité des métadonnées','Transformer les données ponctuelles en polygones'],correct:0,explain:'Un identifiant unique facilite la traçabilité et évite les confusions entre échantillons, résultats analytiques, positions et rapports.'},
 {id:'gc04',domain:'geochem',difficulty:'intermediaire',q:'Pourquoi inclure des blancs et des matériaux de référence certifiés dans une campagne géochimique ?',context:'La qualité des données doit être contrôlée avant l’interprétation.',a:['Pour détecter des contaminations et vérifier l’exactitude ou la dérive analytique','Pour augmenter artificiellement les concentrations','Pour remplacer tous les échantillons de terrain','Pour corriger automatiquement le système de coordonnées'],correct:0,explain:'Les blancs aident à détecter les contaminations ; les matériaux de référence et duplicatas contribuent au contrôle de l’exactitude et de la précision.'},
 {id:'g08',domain:'general',difficulty:'avance',q:'Une discordance angulaire sépare des couches inclinées érodées d’une série plus jeune subhorizontale. Que révèle-t-elle ?',context:'La surface marque une interruption de l’enregistrement géologique.',a:['Une déformation et une érosion antérieures au dépôt de la série supérieure','Une continuité parfaite du dépôt sans interruption','Une fusion complète des deux séries','Une preuve unique de volcanisme récent'],correct:0,explain:'Une discordance angulaire traduit généralement dépôt ancien, déformation/inclinaison, érosion, puis dépôt de couches plus jeunes selon une orientation différente.'},
 {id:'p08',domain:'petroleum',difficulty:'avance',q:'Un réservoir est compartimenté par des failles. Quel effet possible cela peut-il avoir sur le développement ?',context:'Les failles peuvent être conductrices ou constituer des barrières selon leur remplissage et leur histoire.',a:['La connectivité et la communication de pression peuvent varier entre compartiments','Les failles sont toujours parfaitement étanches','Le nombre de compartiments n’a jamais d’impact','La compartimentation garantit un meilleur facteur de récupération'],correct:0,explain:'La transmissibilité des failles dépend de la juxtaposition des couches, des argiles de faille, des fractures et de l’histoire tectonique. Elle influence le drainage et la gestion du réservoir.'},
 {id:'pt08',domain:'petrophysics',difficulty:'avance',q:'Une courbe de gamma ray faible suffit-elle à qualifier un intervalle de réservoir propre et productif ?',context:'Les minéraux radioactifs non argileux, la qualité des pores et les fluides doivent aussi être considérés.',a:['Oui, elle prouve la présence d’hydrocarbures mobiles','Non, il faut intégrer lithologie, porosité, saturation, perméabilité et qualité des mesures','Oui, si la profondeur est grande','Non, car le gamma ray ne mesure rien de géologique'],correct:1,explain:'Un GR faible peut suggérer une faible teneur en minéraux radioactifs, mais ne prouve ni une porosité efficace, ni une saturation favorable, ni la productivité.'},
 {id:'s06',domain:'sedimentology',difficulty:'avance',q:'Dans un système deltaïque, pourquoi la distribution des faciès peut-elle changer rapidement latéralement ?',context:'Les chenaux, lobes, levées et baies évoluent au cours de la progradation et des avulsions.',a:['Parce que les processus et les sous-environnements de dépôt sont spatialement variables et mobiles','Parce que tous les dépôts deltaïques sont homogènes','Parce que la granulométrie ne dépend jamais du courant','Parce que les deltas ne contiennent pas de chenaux'],correct:0,explain:'Les systèmes deltaïques combinent plusieurs sous-environnements et des changements rapides de position des chenaux et lobes, ce qui crée une forte hétérogénéité latérale.'},
 {id:'st05',domain:'structural',difficulty:'avance',q:'Pourquoi les fractures naturelles peuvent-elles améliorer ou réduire la qualité d’un réservoir ?',context:'Leur effet dépend de l’ouverture, de la connectivité, du remplissage minéral et du champ de contraintes.',a:['Elles peuvent créer des voies d’écoulement ou être colmatées et compartimenter le milieu','Elles augmentent toujours la porosité utile','Elles n’ont aucun effet sur l’écoulement','Elles garantissent systématiquement une communication entre puits'],correct:0,explain:'Les fractures peuvent accroître la perméabilité si elles sont ouvertes et connectées, mais leur colmatage ou leur organisation peut limiter les écoulements.'},
 {id:'m06',domain:'mineralogy',difficulty:'avance',q:'Deux minéraux ont la même composition chimique mais des structures cristallines différentes. Comment les appelle-t-on ?',context:'Leurs propriétés physiques peuvent être différentes malgré une composition identique.',a:['Polymorphes','Isotopes','Fossiles directeurs','Alluvions'],correct:0,explain:'Les polymorphes partagent la même composition chimique mais diffèrent par leur structure cristalline, comme calcite et aragonite.'},
 {id:'h05',domain:'hydro',difficulty:'avance',q:'Pourquoi une carte piézométrique est-elle utile pour comprendre un aquifère ?',context:'Les niveaux d’eau sont mesurés dans plusieurs ouvrages à une période comparable.',a:['Elle permet d’estimer la distribution de la charge hydraulique et les directions générales d’écoulement','Elle donne directement la date de formation de l’aquifère','Elle mesure seule la porosité totale','Elle prouve la potabilité de l’eau'],correct:0,explain:'Les lignes d’égale charge hydraulique permettent d’interpréter les gradients et les directions générales d’écoulement, sous réserve de données comparables et de conditions de mesure adaptées.'},
 {id:'gf05',domain:'geophysics',difficulty:'avance',q:'Pourquoi un problème géophysique inverse est-il souvent non unique ?',context:'Plusieurs modèles du sous-sol peuvent expliquer des observations similaires.',a:['Différentes distributions de propriétés peuvent produire des réponses mesurées proches','Parce qu’aucune mesure ne contient d’information','Parce que les roches n’ont pas de propriétés physiques','Parce que les modèles inverses ne peuvent pas être calculés'],correct:0,explain:'L’inversion géophysique est souvent non unique : des modèles différents peuvent expliquer les données. Les contraintes géologiques, les données de puits et l’analyse d’incertitude aident à réduire les solutions plausibles.'},
 {id:'mp05',domain:'mapping',difficulty:'avance',q:'Un modèle numérique de terrain montre une dépression. Quelle vérification est pertinente avant d’en conclure à une structure géomorphologique réelle ?',context:'Le MNT peut contenir des artefacts, des zones sans données ou des erreurs de traitement.',a:['Contrôler la qualité des données, la résolution, les artefacts et confronter au terrain ou à d’autres sources','Conclure immédiatement à un cratère','Ignorer la résolution spatiale','Transformer l’altitude en longitude'],correct:0,explain:'Une dépression peut être réelle ou provenir de trous de données, d’interpolation, de bâtiments/végétation ou de traitement. La validation croisée est importante.'},
 {id:'gc05',domain:'geochem',difficulty:'avance',q:'Une concentration élevée d’un élément dans un sol ne démontre pas automatiquement une pollution. Pourquoi ?',context:'La roche mère peut naturellement être enrichie dans cet élément.',a:['Parce que l’origine doit être évaluée en comparant le fond naturel, le contexte, la spéciation et les sources possibles','Parce que les éléments chimiques ne sont jamais toxiques','Parce qu’une concentration élevée est toujours normale','Parce que le sol n’a aucune relation avec la géologie'],correct:0,explain:'L’évaluation environnementale distingue les enrichissements géogéniques et anthropiques, et considère aussi la forme chimique, la biodisponibilité, les voies d’exposition et les normes applicables.'}
];

