const LEVEL_NAMES = ['Fondations','Notions clés','Compréhension','Application','Analyse','Interprétation','Diagnostic','Expertise','Cas complexe','Maîtrise'];
const LEVEL_DIFFICULTY = level => level<=3?'debutant':level<=6?'intermediaire':'avance';
const LEVEL_MULTIPLIER = level => level<=3?1:level<=6?1.5:2+(level-7)*0.2;
const LEVEL_FRAMES = [
 'Repère le principe fondamental.', 'Explique le concept avec les données disponibles.', 'Choisis l’interprétation la plus cohérente.',
 'Applique le principe à une situation de terrain.', 'Analyse les indices et leurs limites.', 'Compare les hypothèses et leurs conséquences.',
 'Diagnostique la cause la plus plausible.', 'Évalue les incertitudes avant de conclure.', 'Résous le cas en intégrant plusieurs contraintes.', 'Formule la conclusion la plus défendable et vérifiable.'
];
function buildQuestionBank(){
 const bank=[];
 for(const domain of DOMAINS){
  const topics=TOPICS[domain.id]||[];
  for(let level=1;level<=10;level++){
   for(let i=0;i<10;i++){
    const topic=topics[i%topics.length];
    const [topicName,context,baseQuestion,answers,correct,explain]=topic;
    const qText=level===1?baseQuestion:`${LEVEL_FRAMES[level-1]} ${baseQuestion}`;
    const distractors=answers.slice();
    const choices=distractors.map((text,index)=>({text,index}));
    // Add level/domain-specific metadata while keeping a single defensible correct option.
    bank.push({id:`${domain.id}_L${level}_${String(i+1).padStart(2,'0')}`,domain:domain.id,level,difficulty:LEVEL_DIFFICULTY(level),topic:topicName,q:qText,context:`${context} ${level>3?'Niveau de raisonnement : '+LEVEL_FRAMES[level-1]:''}`.trim(),a:choices.map(c=>c.text),correct,explain:`${explain} ${level>=7?'Au niveau '+level+', explicite aussi les hypothèses, les limites des données et les vérifications indépendantes nécessaires.':''}`.trim()});
   }
  }
 }
 return bank;
}
const QUESTIONS = buildQuestionBank();

const DIFFICULTIES = {debutant:{label:'Niveaux 1–3 · Fondations',multiplier:1,seconds:30},intermediaire:{label:'Niveaux 4–6 · Application',multiplier:1.5,seconds:30},avance:{label:'Niveaux 7–10 · Expertise',multiplier:2,seconds:30}};
const LEVELS = [{name:'Explorateur',min:0},{name:'Géologue junior',min:500},{name:'Géologue confirmé',min:1500},{name:'Spécialiste',min:3500},{name:'Expert du sous-sol',min:7000},{name:'Maître géoscientifique',min:12000}];
const $ = (s,root=document)=>root.querySelector(s); const $$ = (s,root=document)=>Array.from(root.querySelectorAll(s));
let appData = loadData(); let currentUserId = localStorage.getItem(CURRENT_KEY) || null; let authMode='signup'; let selectedDomain='all'; let selectedLevel=1; let selectedDifficulty='debutant'; let selectedCount=10; let selectedTime=30; let quiz=null; let timerInterval=null; let toastTimeout=null; let lastSetup=null;

function loadData(){try{const parsed=JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}');return {users:Array.isArray(parsed.users)?parsed.users:[],sessions:Array.isArray(parsed.sessions)?parsed.sessions:[]};}catch{return {users:[],sessions:[]};}}
function saveData(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(appData));}catch{showToast('Stockage indisponible : tes résultats ne pourront pas être conservés.');}}
function currentUser(){return appData.users.find(u=>u.id===currentUserId)||null;}
function makeId(){return 'u_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,8);}
function initials(name){return (name||'G').trim().split(/\s+/).slice(0,2).map(s=>s[0]||'').join('').toUpperCase()||'G';}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function pointsOf(user){return user?.points||0;}
function getLevel(points=0){let result=LEVELS[0];for(const l of LEVELS){if(points>=l.min)result=l;}return result;}
function levelIndex(points=0){return LEVELS.findIndex(l=>l.name===getLevel(points).name);}
function getAccuracy(user){return user&&user.answered?Math.round((user.correct/user.answered)*100):null;}
function formatNumber(n){return Number(n||0).toLocaleString('fr-FR');}
function formatDuration(seconds){const s=Math.max(0,Math.floor(seconds||0));return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;}
function domainById(id){return DOMAINS.find(d=>d.id===id)||DOMAINS[0];}
function showToast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('show'),2900);}
function openModal(id){$(id).classList.add('open');}
function closeModal(id){$(id).classList.remove('open');}
function setAuthMode(mode){authMode=mode;$$('.auth-tab').forEach(b=>b.classList.toggle('active',b.dataset.auth===mode));$('#authTitle').textContent=mode==='signup'?'Rejoins les explorateurs.':'Bon retour sur le terrain.';$('.auth-description').textContent=mode==='signup'?'Crée ton profil local pour enregistrer tes points et suivre ta progression.':'Connecte-toi au profil enregistré dans ce navigateur.';$('#authSubmit').innerHTML=mode==='signup'?'Créer mon profil <span>↗</span>':'Ouvrir mon profil <span>↗</span>';$('#authName').required=mode==='signup';$('#authName').closest('form').querySelector('label[for="authName"]').style.display=mode==='signup'?'block':'none';$('#authName').style.display=mode==='signup'?'block':'none';$('#authEmail').required=false;$('#authError').textContent='';$('#authPassword').value='';$('#authPassword').autocomplete=mode==='signup'?'new-password':'current-password';}
async function passwordHash(password){if(window.crypto?.subtle){const bytes=new TextEncoder().encode(password);const digest=await crypto.subtle.digest('SHA-256',bytes);return Array.from(new Uint8Array(digest)).map(b=>b.toString(16).padStart(2,'0')).join('');}return 'local-'+Array.from(password).reduce((a,c)=>((a<<5)-a+c.charCodeAt(0))|0,0).toString(16);}
function authSubmit(e){e.preventDefault();const name=$('#authName').value.trim();const email=$('#authEmail').value.trim().toLowerCase();const password=$('#authPassword').value;const error=$('#authError');error.textContent='';if(password.length<6){error.textContent='Utilise au moins 6 caractères.';return;}
  (async()=>{const hash=await passwordHash(password);if(authMode==='signup'){if(name.length<2){error.textContent='Le nom doit contenir au moins 2 caractères.';return;}if(appData.users.some(u=>(email&&u.email===email)||u.name.toLowerCase()===name.toLowerCase())){error.textContent='Ce nom ou cet e-mail existe déjà sur cet appareil.';return;}const user={id:makeId(),name,email,passwordHash:hash,createdAt:new Date().toISOString(),points:0,answered:0,correct:0,bestStreak:0,streak:0,games:0,history:[]};appData.users.push(user);currentUserId=user.id;localStorage.setItem(CURRENT_KEY,currentUserId);saveData();closeModal('#authModal');refreshUI();showToast(`Bienvenue ${name} ! Ton profil est prêt.`);}else{const found=appData.users.find(u=>(u.name.toLowerCase()===name.toLowerCase()||(email&&u.email===email))&&u.passwordHash===hash);if(!found){error.textContent='Profil introuvable ou mot de passe incorrect sur cet appareil.';return;}currentUserId=found.id;localStorage.setItem(CURRENT_KEY,currentUserId);closeModal('#authModal');refreshUI();showToast(`Content de te retrouver, ${found.name} !`);}})().catch(()=>{error.textContent='Une erreur est survenue. Réessaie.';});}
function showView(name){if(name==='quiz'&&!quiz)return;$$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${name}`));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===name));const titles={home:'Tableau de bord',play:'Lancer un défi',domains:'Domaines géologiques',leaderboard:'Classement local',profile:'Mon profil',quiz:'Session en cours',results:'Résultats'};$('#breadcrumbCurrent').textContent=titles[name]||'GeoQuiz';$('#sidebar').classList.remove('open');if(name==='home')renderDashboard();if(name==='domains')renderDomains();if(name==='leaderboard')renderLeaderboard();if(name==='profile')renderProfile();if(name==='play')renderSetup();window.scrollTo({top:0,behavior:'smooth'});}
function refreshUI(){const u=currentUser();$('#headerName').textContent=u?u.name:'Invité';$('#headerAvatar').textContent=initials(u?.name);$('#headerLevel').textContent=u?getLevel(u.points).name:'Explorateur';$('#headerStreak').textContent=u?.streak||0;renderDashboard();renderDomains();renderLeaderboard();renderProfile();}
function renderDashboard(){const u=currentUser();$('#statPoints').innerHTML=`${formatNumber(pointsOf(u))} <small>pts</small>`;$('#statAnswered').textContent=formatNumber(u?.answered||0);const acc=getAccuracy(u);$('#statAccuracy').innerHTML=acc===null?'—<small>%</small>':`${acc}<small>%</small>`;$('#accuracyBar').style.width=`${acc||0}%`;const level=getLevel(pointsOf(u));const idx=levelIndex(pointsOf(u));$('#statLevel').innerHTML=`${String(idx+1).padStart(2,'0')} <small>${level.name}</small>`;const next=LEVELS[idx+1];const progress=next?Math.min(100,((pointsOf(u)-level.min)/(next.min-level.min))*100):100;$('#levelBar').style.width=`${progress}%`;$('#nextLevelText').textContent=next?`${formatNumber(next.min-pointsOf(u))} pts avant ${next.name}`:'Niveau maximal atteint';$('#lastActivity').textContent=u?.history?.length?`Dernière session : ${new Date(u.history[0].date).toLocaleDateString('fr-FR')}`:'Ton parcours commence ici';
  $('#homeDomains').innerHTML=DOMAINS.slice(0,4).map(d=>`<button class="domain-mini" data-domain-play="${d.id}"><span class="domain-icon">${d.icon}</span><span><b>${esc(d.name)}</b><small>${esc(d.short)}</small></span><span class="domain-arrow">→</span></button>`).join('');$$('[data-domain-play]').forEach(b=>b.addEventListener('click',()=>{selectedDomain=b.dataset.domainPlay;showView('play');renderSetup();}));
  const recent=(u?.history||[]).slice(0,3);$('#recentActivity').innerHTML=recent.length?recent.map(h=>`<div class="activity-item"><span class="activity-symbol">${h.score>=h.maxScore*.7?'✦':'◈'}</span><div><b>${esc(h.domainName)} · ${esc(h.difficultyLabel)}</b><p>${h.correct}/${h.total} bonnes réponses · ${formatDuration(h.duration)}</p></div><span class="activity-time">+${formatNumber(h.score)} pts</span></div>`).join(''):`<div class="empty-state"><span>◷</span><b>La première aventure t'attend</b><p>Lance un défi pour voir ton évolution ici.</p></div>`;
}
function renderDomains(){const container=$('#allDomains');if(!container)return;container.innerHTML=DOMAINS.map((d,i)=>`<article class="domain-card"><div class="domain-card-top"><span class="domain-icon">${d.icon}</span><span class="domain-tag">${d.tag}</span></div><h3>${esc(d.name)}</h3><p>${esc(d.description)}</p><div class="domain-card-bottom"><span>${QUESTIONS.filter(q=>q.domain===d.id).length} questions · 10 niveaux</span><button data-domain-launch="${d.id}">S'entraîner →</button></div></article>`).join('');$('#domainTotal').textContent=`${DOMAINS.length} domaines`;$$('[data-domain-launch]').forEach(b=>b.addEventListener('click',()=>{selectedDomain=b.dataset.domainLaunch;showView('play');renderSetup();}));
  $('#domainChoices').innerHTML=`<button class="domain-select ${selectedDomain==='all'?'selected':''}" data-domain="all"><span class="domain-icon">✧</span><span><b>Tous les domaines</b><small>Parcours transversal</small></span></button>`+DOMAINS.map(d=>`<button class="domain-select ${selectedDomain===d.id?'selected':''}" data-domain="${d.id}"><span class="domain-icon">${d.icon}</span><span><b>${esc(d.name)}</b><small>${esc(d.short)}</small></span></button>`).join('');$$('[data-domain]').forEach(b=>b.addEventListener('click',()=>{selectedDomain=b.dataset.domain;renderSetup();}));}
function renderSetup(){renderDomains();$$('.difficulty-option').forEach(b=>b.classList.toggle('selected',Number(b.dataset.level)===selectedLevel));$$('.session-option').forEach(b=>b.classList.toggle('selected',Number(b.dataset.count)===selectedCount));$$('.timer-pill').forEach(b=>b.classList.toggle('selected',Number(b.dataset.time)===selectedTime));$('#previewCount').innerHTML=`${selectedCount} <span>questions</span>`;$('#previewDomain').textContent=selectedDomain==='all'?'Toutes les disciplines':domainById(selectedDomain).name;$('#previewDifficulty').textContent=`Niveau ${selectedLevel} · ${LEVEL_NAMES[selectedLevel-1]}`;$('#previewDuration').textContent=`~ ${Math.max(1,Math.ceil(selectedCount*selectedTime/60))} min`;$('#previewMax').textContent=`${formatNumber(selectedCount*(Math.round(100*LEVEL_MULTIPLIER(selectedLevel))+75))} pts`;}
function renderLeaderboard(){const sorted=[...appData.users].sort((a,b)=>(b.points||0)-(a.points||0));$('#leaderboardBody').innerHTML=sorted.length?sorted.map((u,i)=>`<tr><td>${String(i+1).padStart(2,'0')}${i===0?' ✦':''}</td><td><div class="player-cell"><span class="avatar">${initials(u.name)}</span><b>${esc(u.name)}${u.id===currentUserId?' (toi)':''}</b></div></td><td><span class="rank-tag">${esc(getLevel(u.points).name)}</span></td><td>${formatNumber(u.answered)}</td><td>${getAccuracy(u)===null?'—':getAccuracy(u)+'%'}</td><td class="score-cell">${formatNumber(u.points)} pts</td></tr>`).join(''):`<tr><td colspan="6" style="text-align:center;padding:35px;color:#8194a8">Aucun participant. Crée un profil pour apparaître ici.</td></tr>`;}
function renderProfile(){const u=currentUser();$('#profileAvatar').textContent=initials(u?.name);$('#profileName').textContent=u?.name||'Invité';$('#profileEmail').textContent=u?.email||'Profil local';$('#profileRank').textContent=`NIVEAU ${String(levelIndex(pointsOf(u))+1).padStart(2,'0')} · ${getLevel(pointsOf(u)).name.toUpperCase()}`;$('#profilePoints').textContent=formatNumber(u?.points||0);$('#profileGames').textContent=formatNumber(u?.games||0);$('#profileAccuracy').textContent=getAccuracy(u)===null?'—%':getAccuracy(u)+'%';const history=u?.history||[];$('#profileHistory').innerHTML=history.length?history.slice(0,12).map(h=>`<div class="history-entry"><span class="activity-symbol">${h.score>=h.maxScore*.7?'✦':'◈'}</span><div class="history-entry-main"><b>${esc(h.domainName)} · ${esc(h.difficultyLabel)}</b><small>${new Date(h.date).toLocaleString('fr-FR')} · ${h.correct}/${h.total} bonnes réponses</small></div><span class="history-points">+${formatNumber(h.score)}</span></div>`).join(''):`<div class="empty-state"><span>⌁</span><b>Aucune session pour le moment</b><p>Ta première session apparaîtra ici.</p></div>`;}
function shuffled(arr){const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function startQuiz(){const pool=QUESTIONS.filter(q=>(selectedDomain==='all'||q.domain===selectedDomain)&&q.level===selectedLevel);if(pool.length===0){showToast('Pas encore assez de questions dans ce domaine à ce niveau. Essaie un autre niveau.');return;}if(pool.length<selectedCount){showToast(`Ce parcours contient ${pool.length} questions pour le moment. La session utilisera toutes les questions disponibles.`);}const selected=shuffled(pool).slice(0,selectedCount).map(q=>{const choices=q.a.map((text,index)=>({text,correct:index===q.correct}));const mixed=shuffled(choices);return {...q,choices:mixed,correctIndex:mixed.findIndex(a=>a.correct)};});selectedDifficulty=LEVEL_DIFFICULTY(selectedLevel);lastSetup={domain:selectedDomain,difficulty:selectedDifficulty,level:selectedLevel,count:selectedCount,time:selectedTime};quiz={questions:selected,index:0,score:0,correct:0,answered:0,streak:0,bestStreak:0,startedAt:Date.now(),questionStartedAt:Date.now(),secondsLeft:selectedTime,answers:[],locked:false,finished:false};showView('quiz');renderQuestion();startTimer();}
function stopTimer(){if(timerInterval){clearInterval(timerInterval);timerInterval=null;}}
function startTimer(){stopTimer();timerInterval=setInterval(()=>{if(!quiz||quiz.finished||quiz.locked)return;quiz.secondsLeft=Math.max(0,quiz.secondsLeft-0.1);updateTimerUI();if(quiz.secondsLeft<=0){clearInterval(timerInterval);timerInterval=null;handleTimeout();}},100);}
function updateTimerUI(){if(!quiz)return;const max=lastSetup?.time||30;const p=Math.max(0,quiz.secondsLeft/max*100);$('#timerNumber').textContent=Math.ceil(quiz.secondsLeft);$('#timerRing').style.background=`conic-gradient(${p<=20?'var(--red)':p<=45?'var(--orange)':'var(--teal)'} ${p}%, #22394a 0)`;$('#timerRing').classList.toggle('urgent',p<=20);$('#timerRing').classList.toggle('warning',p<=45&&p>20);$('#timerRing').style.setProperty('--timer-progress',`${p}%`);$('#timerBar').style.width=`${p}%`;$('#timerBar').style.background=p<=20?'var(--red)':p<=45?'var(--orange)':'var(--teal)';}
function renderQuestion(){if(!quiz)return;const q=quiz.questions[quiz.index];quiz.locked=false;quiz.secondsLeft=lastSetup.time;quiz.questionStartedAt=Date.now();$('#questionNumber').textContent=String(quiz.index+1).padStart(2,'0');$('#questionTotal').textContent=quiz.questions.length;$('#quizProgress').style.width=`${quiz.index/quiz.questions.length*100}%`;const d=domainById(q.domain);$('#questionCategory').textContent=d.name.toUpperCase();$('#questionDifficulty').textContent=`NIVEAU ${q.level} · ${LEVEL_NAMES[q.level-1].toUpperCase()}`;$('#questionPoints').textContent=Math.round(100*LEVEL_MULTIPLIER(q.level));$('#questionIndex').textContent=`Q.${String(quiz.index+1).padStart(2,'0')} — ${q.level>=8?'EXPERTISE':q.level>=4?'APPLICATION':'FONDAMENTAUX'}`;$('#questionText').textContent=q.q;$('#questionContext').textContent=q.context||'';$('#answerList').innerHTML=q.choices.map((a,i)=>`<button class="answer-option" data-answer="${i}"><span class="answer-letter">${i+1}</span><span class="answer-text">${esc(a.text)}</span><span class="answer-check">✓</span></button>`).join('');$$('[data-answer]').forEach(b=>b.addEventListener('click',()=>chooseAnswer(Number(b.dataset.answer))));$('#answerFeedback').className='answer-feedback';$('#answerFeedback').textContent='';$('#nextQuestion').disabled=true;$('#nextQuestion').innerHTML=quiz.index===quiz.questions.length-1?'Voir mes résultats <span>↗</span>':'Question suivante <span>→</span>';updateQuizStats();updateTimerUI();}
function chooseAnswer(choiceIndex){if(!quiz||quiz.locked)return;const q=quiz.questions[quiz.index];quiz.locked=true;stopTimer();const chosen=q.choices[choiceIndex];const isCorrect=!!chosen?.correct;const elapsed=(Date.now()-quiz.questionStartedAt)/1000;const timeLeft=Math.max(0,quiz.secondsLeft);let gained=0;if(isCorrect){quiz.correct++;quiz.streak++;quiz.bestStreak=Math.max(quiz.bestStreak,quiz.streak);const base=Math.round(100*LEVEL_MULTIPLIER(q.level));const speedBonus=Math.round((timeLeft/(lastSetup.time||30))*50);const streakBonus=quiz.streak>=3?25:0;gained=base+speedBonus+streakBonus;quiz.score+=gained;}else{quiz.streak=0;}quiz.answered++;quiz.answers.push({questionId:q.id,choiceIndex,correct:isCorrect,chosen:chosen?.text||'Aucune réponse',correctAnswer:q.choices[q.correctIndex].text,elapsed:Math.round(elapsed),gained});$$('[data-answer]').forEach((b,i)=>{b.disabled=true;if(q.choices[i].correct)b.classList.add('correct');else if(i===choiceIndex)b.classList.add('incorrect');});const feedback=$('#answerFeedback');feedback.className=`answer-feedback ${isCorrect?'good':'bad'}`;feedback.innerHTML=`<b>${isCorrect?`Bonne réponse ! +${gained} pts`:'Pas tout à fait.'}</b> ${esc(q.explain)}`;$('#nextQuestion').disabled=false;$('#quizProgress').style.width=`${(quiz.index+1)/quiz.questions.length*100}%`;updateQuizStats();}
function handleTimeout(){if(!quiz||quiz.locked)return;quiz.locked=true;const q=quiz.questions[quiz.index];quiz.streak=0;quiz.answered++;quiz.answers.push({questionId:q.id,choiceIndex:-1,correct:false,chosen:'Temps écoulé',correctAnswer:q.choices[q.correctIndex].text,elapsed:lastSetup.time,gained:0});$$('[data-answer]').forEach((b,i)=>{b.disabled=true;if(q.choices[i].correct)b.classList.add('correct');});const feedback=$('#answerFeedback');feedback.className='answer-feedback bad';feedback.innerHTML=`<b>Temps écoulé.</b> ${esc(q.explain)}`;$('#nextQuestion').disabled=false;$('#quizProgress').style.width=`${(quiz.index+1)/quiz.questions.length*100}%`;updateQuizStats();}
function updateQuizStats(){if(!quiz)return;$('#liveScore').innerHTML=`${formatNumber(quiz.score)} <small>pts</small>`;$('#liveCorrect').textContent=quiz.correct;$('#liveStreak').textContent=`${quiz.streak} 🔥`;$('#liveBonus').textContent=quiz.streak>=3?'+25 pts':'Activé';}
function nextQuestion(){if(!quiz||!quiz.locked)return;if(quiz.index<quiz.questions.length-1){quiz.index++;renderQuestion();startTimer();}else finishQuiz();}
function finishQuiz(){if(!quiz||quiz.finished)return;stopTimer();quiz.finished=true;const duration=Math.round((Date.now()-quiz.startedAt)/1000);const total=quiz.questions.length;const maxScore=total*(Math.round(100*LEVEL_MULTIPLIER(lastSetup.level||1))+50+25);const accuracy=Math.round(quiz.correct/total*100);const u=currentUser();if(u){u.points=(u.points||0)+quiz.score;u.answered=(u.answered||0)+quiz.answered;u.correct=(u.correct||0)+quiz.correct;u.games=(u.games||0)+1;u.bestStreak=Math.max(u.bestStreak||0,quiz.bestStreak);u.streak=quiz.bestStreak;const historyItem={id:makeId(),date:new Date().toISOString(),domainName:lastSetup.domain==='all'?'Tous les domaines':domainById(lastSetup.domain).name,difficultyLabel:`Niveau ${lastSetup.level} · ${LEVEL_NAMES[(lastSetup.level||1)-1]}`,score:quiz.score,maxScore,correct:quiz.correct,total,duration,accuracy};u.history=u.history||[];u.history.unshift(historyItem);u.history=u.history.slice(0,50);saveData();}
  $('#finalScore').textContent=formatNumber(quiz.score);$('#resultCorrect').textContent=`${quiz.correct}/${total}`;$('#resultAccuracy').textContent=`${accuracy}%`;$('#resultTime').textContent=formatDuration(duration);let title='Belle exploration !',message='Chaque session te donne une nouvelle occasion de mieux raisonner sur le sous-sol.';if(accuracy>=90){title='Tu maîtrises le terrain !';message='Excellent résultat. Continue à challenger tes acquis et à approfondir les explications.';}else if(accuracy>=70){title='Solide progression !';message='Tu as de bons réflexes. Revois les explications des questions manquées pour consolider tes acquis.';}else if(accuracy<40){title='La prochaine couche t’attend.';message='Utilise la correction détaillée comme une mini-révision, puis retente une session à ton rythme.';}$('#resultsTitle').textContent=title;$('#resultsSubtitle').textContent=`${lastSetup.domain==='all'?'Parcours transversal':domainById(lastSetup.domain).name} · Niveau ${lastSetup.level} — ${LEVEL_NAMES[(lastSetup.level||1)-1]}`;$('#resultsMessage').textContent=message;$('#resultsIcon').textContent=accuracy>=70?'✦':'⌁';$('#reviewPanel').classList.add('hidden');$('#reviewAnswers').textContent='Revoir les réponses';$('#reviewList').innerHTML=quiz.questions.map((q,i)=>{const a=quiz.answers[i];return `<div class="review-item"><h4>${i+1}. ${esc(q.q)}</h4><p class="review-answer">Ta réponse : <strong style="color:${a?.correct?'var(--teal)':'var(--red)'}">${esc(a?.chosen||'Sans réponse')}</strong></p>${!a?.correct?`<p class="review-answer">Réponse attendue : <strong>${esc(a?.correctAnswer||q.choices[q.correctIndex].text)}</strong></p>`:''}<p class="review-explanation">${esc(q.explain)}</p></div>`;}).join('');showView('results');refreshUI();}
function quitQuiz(){if(!quiz||quiz.finished){showView('home');return;}if(confirm('Quitter cette session ? La progression de cette partie ne sera pas enregistrée.')){stopTimer();quiz=null;showView('home');}}
function retryQuiz(){if(lastSetup){selectedDomain=lastSetup.domain;selectedLevel=lastSetup.level||1;selectedDifficulty=LEVEL_DIFFICULTY(selectedLevel);selectedCount=lastSetup.count;selectedTime=lastSetup.time;}startQuiz();}
function editProfile(){const u=currentUser();if(!u){setAuthMode('signup');openModal('#authModal');return;}const next=prompt('Nouveau nom de participant :',u.name);if(next===null)return;const name=next.trim();if(name.length<2||name.length>32){showToast('Le nom doit contenir entre 2 et 32 caractères.');return;}if(appData.users.some(x=>x.id!==u.id&&x.name.toLowerCase()===name.toLowerCase())){showToast('Ce nom est déjà utilisé sur cet appareil.');return;}u.name=name;saveData();refreshUI();showToast('Profil mis à jour.');}
function logout(){currentUserId=null;localStorage.removeItem(CURRENT_KEY);refreshUI();setAuthMode('login');$('#authName').value='';$('#authEmail').value='';openModal('#authModal');}
function resetData(){const u=currentUser();if(!u){showToast('Aucun profil actif.');return;}if(!confirm(`Effacer le profil « ${u.name} » et toutes ses statistiques sur cet appareil ? Cette action est irréversible.`))return;appData.users=appData.users.filter(x=>x.id!==u.id);appData.sessions=appData.sessions.filter(s=>s.userId!==u.id);currentUserId=null;localStorage.removeItem(CURRENT_KEY);saveData();refreshUI();setAuthMode('signup');openModal('#authModal');}
function init(){
  $$('.nav-item').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));
  $$('[data-goto]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.goto)));
  $('#heroStart').addEventListener('click',()=>showView('play'));$('#bannerStart').addEventListener('click',()=>{selectedDomain='all';selectedLevel=5;selectedDifficulty=LEVEL_DIFFICULTY(selectedLevel);selectedCount=15;selectedTime=30;showView('play');renderSetup();});$('#exploreDomains').addEventListener('click',()=>showView('domains'));$('#dailyChallenge').addEventListener('click',()=>{selectedDomain='all';selectedLevel=3;selectedDifficulty=LEVEL_DIFFICULTY(selectedLevel);selectedCount=5;selectedTime=20;showView('play');renderSetup();});
  $$('.difficulty-option').forEach(b=>b.addEventListener('click',()=>{selectedLevel=Number(b.dataset.level)||1;selectedDifficulty=LEVEL_DIFFICULTY(selectedLevel);renderSetup();}));$$('.session-option').forEach(b=>b.addEventListener('click',()=>{selectedCount=Number(b.dataset.count);renderSetup();}));$$('.timer-pill').forEach(b=>b.addEventListener('click',()=>{selectedTime=Number(b.dataset.time);renderSetup();}));$('#startQuiz').addEventListener('click',startQuiz);$('#nextQuestion').addEventListener('click',nextQuestion);$('#quitQuiz').addEventListener('click',quitQuiz);$('#retryQuiz').addEventListener('click',retryQuiz);$('#resultsHome').addEventListener('click',()=>showView('home'));$('#reviewAnswers').addEventListener('click',()=>{const panel=$('#reviewPanel');panel.classList.toggle('hidden');$('#reviewAnswers').textContent=panel.classList.contains('hidden')?'Revoir les réponses':'Masquer la correction';if(!panel.classList.contains('hidden'))panel.scrollIntoView({behavior:'smooth',block:'start'});});
  $$('.auth-tab').forEach(b=>b.addEventListener('click',()=>setAuthMode(b.dataset.auth)));$('#authForm').addEventListener('submit',authSubmit);$('#closeAuth').addEventListener('click',()=>closeModal('#authModal'));$('#userChip').addEventListener('click',()=>{if(currentUser()){showView('profile');}else{setAuthMode('signup');openModal('#authModal');}});$('#editProfile').addEventListener('click',editProfile);$('#logoutBtn').addEventListener('click',logout);$('#resetData').addEventListener('click',resetData);$('#mobileMenu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#aboutBtn').addEventListener('click',()=>openModal('#aboutModal'));$('#closeAbout').addEventListener('click',()=>closeModal('#aboutModal'));$('#closeAboutBtn').addEventListener('click',()=>closeModal('#aboutModal'));
  ['#authModal','#aboutModal'].forEach(id=>$(id).addEventListener('click',e=>{if(e.target===$(id))closeModal(id);}));document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal('#aboutModal');if(currentUserId)closeModal('#authModal');if(quiz&&!quiz.finished&&$('#view-quiz').classList.contains('active')){} }if($('#view-quiz').classList.contains('active')&&quiz&&!quiz.locked&&!e.ctrlKey&&!e.metaKey){const n=Number(e.key);if(n>=1&&n<=4)chooseAnswer(n-1);}});
  renderSetup();refreshUI();if(!currentUser()){setAuthMode('signup');openModal('#authModal');}else{showView('home');}
}
document.addEventListener('DOMContentLoaded',init);
